//! A small PEG engine whose failure reporting mirrors the behaviour of the
//! parser generator the original shell was built with: the position of the
//! furthest failed rule attempt is remembered together with the set of rules
//! that were tried there, and the resulting message is rendered with a source
//! excerpt and a caret.

use std::fmt;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Atomicity {
    /// Whitespace is skipped between sequence items; inner rules keep their
    /// own tokens and are reported on failure.
    NonAtomic,
    /// No whitespace skipping, but inner rules still produce tokens.
    Compound,
    /// No whitespace skipping, no inner tokens, no inner failure reporting.
    Atomic,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Lookahead {
    None,
    Positive,
    Negative,
}

/// A grammar expression.
pub enum Expr {
    /// Match a literal string.
    Str(&'static str),
    /// Match one character out of a set.
    Set(&'static str),
    /// Match one character that is *not* in a set (fails at end of input).
    NotSet(&'static str),
    /// Match any single character.
    Any,
    /// Match one character in an inclusive range.
    Range(char, char),
    /// Invoke another rule.
    Rule(u16),
    Seq(Vec<Expr>),
    Choice(Vec<Expr>),
    Opt(Box<Expr>),
    Star(Box<Expr>),
    Plus(Box<Expr>),
    /// `&e`
    Ahead(Box<Expr>),
    /// `!e`
    Not(Box<Expr>),
    /// Always succeeds without consuming anything.
    Empty,
}

pub struct RuleDef {
    pub name: &'static str,
    /// Silent rules leave no trace: no token pair, no failure report.
    pub silent: bool,
    /// `None` keeps the surrounding atomicity.
    pub atomicity: Option<Atomicity>,
    pub expr: Expr,
}

pub struct Grammar {
    pub rules: Vec<RuleDef>,
    /// Rule invoked between sequence items when not atomic.
    pub whitespace: Option<u16>,
    /// Rule invoked (after whitespace) between sequence items when not atomic.
    pub comment: Option<u16>,
}

impl Grammar {
    pub fn name(&self, id: u16) -> &'static str {
        self.rules[id as usize].name
    }
}

enum Tok {
    Start { rule: u16, pos: usize },
    End { rule: u16, pos: usize },
}

struct State<'a> {
    input: &'a str,
    bytes: &'a [u8],
    pos: usize,
    attempt_pos: usize,
    positives: Vec<u16>,
    negatives: Vec<u16>,
    lookahead: Lookahead,
    atomicity: Atomicity,
    toks: Vec<Tok>,
    /// Guards against runaway recursion on pathological input.
    depth: u32,
}

/// One node of the resulting parse tree.
pub struct Node {
    pub rule: u16,
    pub start: usize,
    pub end: usize,
    pub children: Vec<Node>,
}

impl Node {
    pub fn text<'a>(&self, input: &'a str) -> &'a str {
        &input[self.start..self.end]
    }
    pub fn child(&self, rule: u16) -> Option<&Node> {
        self.children.iter().find(|c| c.rule == rule)
    }
    pub fn children_of(&self, rule: u16) -> impl Iterator<Item = &Node> {
        self.children.iter().filter(move |c| c.rule == rule)
    }
}

/// A parse failure, rendered the same way the original shell renders it.
pub struct ParseError {
    pub pos: usize,
    pub line: usize,
    pub col: usize,
    pub line_text: String,
    pub positives: Vec<&'static str>,
    pub negatives: Vec<&'static str>,
}

fn enumerate(items: &[&'static str]) -> String {
    match items.len() {
        0 => String::new(),
        1 => items[0].to_string(),
        2 => format!("{} or {}", items[0], items[1]),
        n => {
            let head: Vec<&str> = items[..n - 1].to_vec();
            format!("{}, or {}", head.join(", "), items[n - 1])
        }
    }
}

impl ParseError {
    pub fn message(&self) -> String {
        match (self.negatives.is_empty(), self.positives.is_empty()) {
            (false, false) => format!(
                "unexpected {}; expected {}",
                enumerate(&self.negatives),
                enumerate(&self.positives)
            ),
            (false, true) => format!("unexpected {}", enumerate(&self.negatives)),
            (true, false) => format!("expected {}", enumerate(&self.positives)),
            (true, true) => "unknown parsing error".to_string(),
        }
    }
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let ln = self.line.to_string();
        let pad = " ".repeat(ln.len());
        let mut underline = String::new();
        for c in self.line_text.chars().take(self.col - 1) {
            underline.push(if c == '\t' { '\t' } else { ' ' });
        }
        underline.push_str("^---");
        write!(
            f,
            "{p} --> {l}:{c}\n\
             {p} |\n\
             {ln} | {line}\n\
             {p} | {under}\n\
             {p} |\n\
             {p} = {msg}",
            p = pad,
            l = self.line,
            c = self.col,
            ln = ln,
            line = self.line_text,
            under = underline,
            msg = self.message()
        )
    }
}

const MAX_DEPTH: u32 = 400;

impl<'a> State<'a> {
    fn attempts_len(&self) -> usize {
        self.positives.len()
    }

    /// Record a failed attempt of `rule` that began at `pos`.
    fn track(&mut self, rule: u16, pos: usize, pos_idx: usize, neg_idx: usize) {
        if self.atomicity == Atomicity::Atomic {
            return;
        }
        if pos > self.attempt_pos {
            self.positives.clear();
            self.negatives.clear();
            self.attempt_pos = pos;
        } else if pos == self.attempt_pos {
            self.positives.truncate(pos_idx);
            self.negatives.truncate(neg_idx);
        } else {
            return;
        }
        if self.lookahead == Lookahead::Negative {
            self.negatives.push(rule);
        } else {
            self.positives.push(rule);
        }
    }

    fn skip(&mut self, g: &Grammar) {
        if self.atomicity != Atomicity::NonAtomic {
            return;
        }
        loop {
            let before = self.pos;
            if let Some(w) = g.whitespace {
                while self.run_rule(g, w).is_ok() && self.pos > before {
                    // keep eating whitespace
                    if self.pos == before {
                        break;
                    }
                }
            }
            let mid = self.pos;
            if let Some(c) = g.comment {
                if self.run_rule(g, c).is_err() {
                    self.pos = mid;
                    break;
                }
            } else {
                break;
            }
            if self.pos == before {
                break;
            }
        }
    }

    fn run_rule(&mut self, g: &Grammar, id: u16) -> Result<(), ()> {
        let def = &g.rules[id as usize];
        if def.silent {
            let saved = self.atomicity;
            if let Some(a) = def.atomicity {
                if self.atomicity != Atomicity::Atomic {
                    self.atomicity = a;
                }
            }
            let r = self.run(g, &def.expr);
            self.atomicity = saved;
            return r;
        }

        let start = self.pos;
        let tok_index = self.toks.len();
        let (pos_idx, neg_idx) = if start == self.attempt_pos {
            (self.positives.len(), self.negatives.len())
        } else {
            (0, 0)
        };
        let emit = self.lookahead == Lookahead::None && self.atomicity != Atomicity::Atomic;
        if emit {
            self.toks.push(Tok::Start { rule: id, pos: start });
        }

        let saved = self.atomicity;
        if let Some(a) = def.atomicity {
            if self.atomicity != Atomicity::Atomic {
                self.atomicity = a;
            }
        }
        let r = self.run(g, &def.expr);
        self.atomicity = saved;

        match r {
            Ok(()) => {
                if emit {
                    let end = self.pos;
                    self.toks.push(Tok::End { rule: id, pos: end });
                }
                Ok(())
            }
            Err(()) => {
                if emit {
                    self.toks.truncate(tok_index);
                }
                self.track(id, start, pos_idx, neg_idx);
                Err(())
            }
        }
    }

    fn run(&mut self, g: &Grammar, e: &Expr) -> Result<(), ()> {
        match e {
            Expr::Empty => Ok(()),
            Expr::Str(s) => {
                if self.bytes.len() - self.pos >= s.len()
                    && &self.input[self.pos..self.pos + s.len()] == *s
                {
                    self.pos += s.len();
                    Ok(())
                } else {
                    Err(())
                }
            }
            Expr::Set(s) => match self.peek_char() {
                Some(c) if s.contains(c) => {
                    self.pos += c.len_utf8();
                    Ok(())
                }
                _ => Err(()),
            },
            Expr::NotSet(s) => match self.peek_char() {
                Some(c) if !s.contains(c) => {
                    self.pos += c.len_utf8();
                    Ok(())
                }
                _ => Err(()),
            },
            Expr::Any => match self.peek_char() {
                Some(c) => {
                    self.pos += c.len_utf8();
                    Ok(())
                }
                None => Err(()),
            },
            Expr::Range(a, b) => match self.peek_char() {
                Some(c) if c >= *a && c <= *b => {
                    self.pos += c.len_utf8();
                    Ok(())
                }
                _ => Err(()),
            },
            Expr::Rule(id) => {
                if self.depth >= MAX_DEPTH {
                    return Err(());
                }
                self.depth += 1;
                let r = self.run_rule(g, *id);
                self.depth -= 1;
                r
            }
            Expr::Seq(items) => {
                let start = self.pos;
                let tok = self.toks.len();
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        self.skip(g);
                    }
                    if self.run(g, item).is_err() {
                        self.pos = start;
                        self.toks.truncate(tok);
                        return Err(());
                    }
                }
                Ok(())
            }
            Expr::Choice(items) => {
                let start = self.pos;
                let tok = self.toks.len();
                for item in items {
                    if self.run(g, item).is_ok() {
                        return Ok(());
                    }
                    self.pos = start;
                    self.toks.truncate(tok);
                }
                Err(())
            }
            Expr::Opt(inner) => {
                let start = self.pos;
                let tok = self.toks.len();
                if self.run(g, inner).is_err() {
                    self.pos = start;
                    self.toks.truncate(tok);
                }
                Ok(())
            }
            Expr::Star(inner) => {
                self.repeat(g, inner, 0);
                Ok(())
            }
            Expr::Plus(inner) => {
                let start = self.pos;
                let tok = self.toks.len();
                if self.run(g, inner).is_err() {
                    self.pos = start;
                    self.toks.truncate(tok);
                    return Err(());
                }
                self.repeat(g, inner, 1);
                Ok(())
            }
            Expr::Ahead(inner) => {
                let start = self.pos;
                let tok = self.toks.len();
                let saved = self.lookahead;
                if self.lookahead == Lookahead::None {
                    self.lookahead = Lookahead::Positive;
                }
                let r = self.run(g, inner);
                self.lookahead = saved;
                self.pos = start;
                self.toks.truncate(tok);
                r
            }
            Expr::Not(inner) => {
                let start = self.pos;
                let tok = self.toks.len();
                let saved = self.lookahead;
                self.lookahead = Lookahead::Negative;
                let r = self.run(g, inner);
                self.lookahead = saved;
                self.pos = start;
                self.toks.truncate(tok);
                match r {
                    Ok(()) => Err(()),
                    Err(()) => Ok(()),
                }
            }
        }
    }

    fn repeat(&mut self, g: &Grammar, inner: &Expr, already: usize) {
        let mut n = already;
        loop {
            let before = self.pos;
            let tok = self.toks.len();
            if n > 0 {
                self.skip(g);
            }
            if self.run(g, inner).is_err() {
                self.pos = before;
                self.toks.truncate(tok);
                return;
            }
            if self.pos == before {
                // Zero-width match: stop to avoid looping forever.
                return;
            }
            n += 1;
        }
    }

    fn peek_char(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }
}

fn build_tree(toks: &[Tok], from: &mut usize) -> Node {
    let (rule, start) = match toks[*from] {
        Tok::Start { rule, pos } => (rule, pos),
        Tok::End { .. } => unreachable!(),
    };
    *from += 1;
    let mut children = Vec::new();
    loop {
        match toks[*from] {
            Tok::End { pos, .. } => {
                *from += 1;
                return Node { rule, start, end: pos, children };
            }
            Tok::Start { .. } => children.push(build_tree(toks, from)),
        }
    }
}

fn line_col(input: &str, pos: usize) -> (usize, usize, String) {
    let mut line = 1usize;
    let mut line_start = 0usize;
    for (i, b) in input.as_bytes().iter().enumerate() {
        if i >= pos {
            break;
        }
        if *b == b'\n' {
            line += 1;
            line_start = i + 1;
        }
    }
    let mut line_end = line_start;
    let bytes = input.as_bytes();
    while line_end < bytes.len() && bytes[line_end] != b'\n' {
        line_end += 1;
    }
    let col = input[line_start..pos].chars().count() + 1;
    let mut text = input[line_start..line_end].to_string();
    if text.ends_with('\r') {
        text.pop();
    }
    (line, col, text)
}

/// Parse `input` starting from rule `start`, returning the parse tree.
pub fn parse(g: &Grammar, start: u16, input: &str) -> Result<Node, ParseError> {
    let mut st = State {
        input,
        bytes: input.as_bytes(),
        pos: 0,
        attempt_pos: 0,
        positives: Vec::new(),
        negatives: Vec::new(),
        lookahead: Lookahead::None,
        atomicity: Atomicity::NonAtomic,
        toks: Vec::new(),
        depth: 0,
    };
    match st.run_rule(g, start) {
        Ok(()) => {
            let mut i = 0usize;
            let node = build_tree(&st.toks, &mut i);
            Ok(node)
        }
        Err(()) => {
            let mut pos = st.positives.clone();
            pos.sort_unstable();
            pos.dedup();
            let mut neg = st.negatives.clone();
            neg.sort_unstable();
            neg.dedup();
            let (line, col, line_text) = line_col(input, st.attempt_pos);
            Err(ParseError {
                pos: st.attempt_pos,
                line,
                col,
                line_text,
                positives: pos.into_iter().map(|r| g.name(r)).collect(),
                negatives: neg.into_iter().map(|r| g.name(r)).collect(),
            })
        }
    }
}

/// Convenience helpers for building grammars.
pub mod build {
    use super::Expr;

    pub fn seq(v: Vec<Expr>) -> Expr {
        Expr::Seq(v)
    }
    pub fn choice(v: Vec<Expr>) -> Expr {
        Expr::Choice(v)
    }
    pub fn opt(e: Expr) -> Expr {
        Expr::Opt(Box::new(e))
    }
    pub fn star(e: Expr) -> Expr {
        Expr::Star(Box::new(e))
    }
    pub fn plus(e: Expr) -> Expr {
        Expr::Plus(Box::new(e))
    }
    pub fn ahead(e: Expr) -> Expr {
        Expr::Ahead(Box::new(e))
    }
    pub fn not(e: Expr) -> Expr {
        Expr::Not(Box::new(e))
    }
    pub fn s(t: &'static str) -> Expr {
        Expr::Str(t)
    }
    pub fn set(t: &'static str) -> Expr {
        Expr::Set(t)
    }
    pub fn nset(t: &'static str) -> Expr {
        Expr::NotSet(t)
    }
    pub fn r(id: u16) -> Expr {
        Expr::Rule(id)
    }
    pub fn range(a: char, b: char) -> Expr {
        Expr::Range(a, b)
    }
}

